import { consumeBudgets, rateLimitHttpError } from "@/lib/rate-limit";
import "server-only";
import { auth } from "@/auth";
import { db } from "@/lib/db";
import { BillingError, billingConfig } from "@/lib/billing/config";

export const privateBillingHeaders = {
  "Cache-Control": "private, no-store",
  "X-Content-Type-Options": "nosniff",
};
export async function billingSessionUser() {
  const session = await auth();
  if (!session?.user?.id)
    throw new BillingError("UNAUTHENTICATED", "Sign in first.", 401);
  const user = await db.user.findUnique({
    where: { id: session.user.id },
    select: { id: true, deletionRequestedAt: true, isSuspended: true },
  });
  if (!user || user.deletionRequestedAt)
    throw new BillingError("ACCOUNT_UNAVAILABLE", "Account unavailable.", 403);
  return user.id;
}
export function requireBillingOrigin(request: Request) {
  const origin = request.headers.get("origin");
  const configuredOrigin = billingConfig().origin;
  const isCanonicalProductionOrigin =
    configuredOrigin === "https://mailloop.in" &&
    origin === "https://www.mailloop.in";
  if (origin !== configuredOrigin && !isCanonicalProductionOrigin)
    throw new BillingError("INVALID_ORIGIN", "Invalid request origin.", 403);
}
export function billingHttpError(error: unknown) {
  const limited = rateLimitHttpError(error);
  if (limited) return limited;
  const known = error instanceof BillingError;
  return Response.json(
    {
      error: known ? error.message : "Billing is temporarily unavailable.",
      code: known ? error.code : "BILLING_UNAVAILABLE",
    },
    {
      status: known ? error.status : 503,
      headers: {
        ...privateBillingHeaders,
        ...(known && error.status === 429
          ? { "Retry-After": String(error.retryAfter ?? 60) }
          : {}),
      },
    },
  );
}

export const billingRequestLimits = {
  checkout: 5,
  portal: 10,
  cancel: 10,
  status: 30,
} as const;
export async function limitBillingRequest(
  userId: string,
  operation: keyof typeof billingRequestLimits,
) {
  await consumeBudgets(userId, [
    operation === "portal" || operation === "cancel"
      ? "billingManagement"
      : operation,
  ]);
}
